    chronicleSea1Lore:
      'Ancienne artère marchande de l’Anse Libre. Son grand phare éteint, les brumes cachent les récifs tandis que le brigantin Croc Pourpre exige tribut.',
    chronicleSea2Lore:
      'Une fosse volcanique noyée de cendres. La frégate Bûcher Cendré sème des barils de poix enflammée pour brûler chaque coque rebelle.',
