    chronicleOathTitle: 'Schwur des Schwarzen Wimpels',
    chronicleOathBody:
      'Als die Eiserne Krone die stillen Leuchtfeuer löschte, hisste die Freie Bucht den Schwarzen Wimpel, um jedes Feuer neu zu entfachen und die drei Blockade-Flaggschiffe zu brechen.',
    chronicleSea1Lore:
      'Einst die Handelsader der Freien Bucht. Nun verbergen Nebel die Riffe, während die Karmesin-Klaue blutigen Zoll fordert.',
    chronicleSea2Lore:
      'Ein vulkanischer Graben voller Glutböen. Die Fregatte Aschenglut flutet die Fahrrinnen mit Brandfässern.',
    chronicleSea3Lore:
      'Wo drei Strömungen den Horizont zerreißen. Admiral Vexmoor ankerte die Schwarze Krone direkt am Auge des Mahlstroms.',
    chronicleLockedSeaHint: 'Schalte diesen Akt frei, um das Logbuch zu entsiegeln.',
    chronicleOfficerVaneLore:
      'Aus der Kronflotte entlassen, als er keinen Fischerhafen beschießen wollte. Vane gießt seine Messingrohre selbst.',
