    chronicleSecret2Lore: 'Ein Wogensprung mitten über den Strudel weckt den Abgrund unter dem Kiel.',
    chronicleSecret3Lore: 'Altes Kiefernharz der Küstenpfannen entzündet sich noch am Schein vorbeiziehender Schiffe.',
    chronicleSecret4Lore: 'Donner einer Breitseite im Lichtkegel sprengt das Salz von der versunkenen Glocke.',
    chronicleSecret5Lore: 'Bei gestrichenen Segeln in der Stille gibt das Nebelwrack seinen verborgenen Schatz frei.',
    chronicleSecret6Lore: 'Kettenschüsse schließen den Kupferkreis und lenken Himmelsblitze auf feindliche Masten.',
    chronicleSecret7Lore: 'Zwischen scharfen Felsen wartet die Truhe mit schwerem Ring für eine Harpunenwinde.',
